// Fiber structure (simplified):
{
  type: ComponentType,
  stateNode: DOMNode | ComponentInstance,
  child: Fiber | null,
  sibling: Fiber | null,
  return: Fiber | null,
  effectTag: 'UPDATE' | 'PLACEMENT' | 'DELETION',
  alternate: Fiber | null  // work-in-progress or current
}

// React's internal hook structure (simplified):
// fiber.memoizedState -> Hook1 -> Hook2 -> Hook3 -> null
// Each render: React walks this list in order; index = call order

// useLayoutEffect - prevents flash of wrong content
useLayoutEffect(() => {
  const { height } = ref.current.getBoundingClientRect();
  setTooltipPosition(height);
}, [dependency]);

// Lifted state - both inputs share same source of truth
